// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 10 ether);
        vm.deal(address(c), 1 ether);

        vm.prank(address(0x1));
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(bytes32(0))));

        vm.roll(12);

        vm.prank(address(0x1));
        // In the reference, guesses[0x1].block was block.number+1 = 11, block.number (12) > 11, so settle() succeeds and transfers 2 ether.
        // In the bug, guesses[0x1].block was block.number = 10, block.number (12) > 10, but the answer uses blockhash(10) which is non-zero, so if guess matches it transfers; but we need the observable difference.
        // Actually the bug sets block = block.number (10), settle requires block.number > guesses[msg.sender].block, here 12 > 10 true, so both execute. The claim says P and M differ in lockInGuess state; but here we test the settle behavior difference more clearly: warp to block 11 for bug so block.number (11) is not > guessed block (10), reverts.
        // Let's adjust: after lockInGuess at block 10, reference has block=11, bug has block=10. Warp to block 11: reference has block.number (11) > 11? false, so revert. Warp to block 12: reference block.number=12 > 11 true; bug block.number=12 > 10 true. To see divergence, use block 11: reference reverts (since require block.number > guesses[msg.sender].block fails because 11 > 11 is false), bug does NOT revert because 11 > 10 is true. So at block 11, reference reverts, bug succeeds.
        vm.roll(11);

        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }
        // In reference: guesses[0x1].block == 11, block.number == 11, require(block.number > guesses[...].block) fails => revert => ok = false
        // In bug: guesses[0x1].block == 10, block.number == 11, require passes, answer = keccak256(blockhash(10)) which is non-zero, guess might not match but we don't care; no revert => ok = true
        assertTrue(ok == false);
    }
}

