pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address player = address(0x1234);
        vm.deal(player, 2 ether);

        // First call should succeed
        vm.prank(player);
        c.lockInGuess{value: 1 ether}(keccak256("test"));

        // Second call by same sender: reference reverts, buggy allows
        bool secondOk = false;
        vm.prank(player);
        vm.deal(player, 1 ether); // still has ether from earlier
        try c.lockInGuess{value: 1 ether}(keccak256("test2")) {
            secondOk = true;
        } catch {
            secondOk = false;
        }

        // In reference contract, second call reverts (secondOk == false)
        // In buggy contract, second call succeeds (secondOk == true)
        // Assert that it reverts (correct behavior)
        assertTrue(!secondOk);
    }
}

