pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with initial 1 ether (constructor requires msg.value == 1 ether)
        // The contract already has 1 ether from deployment; fund Alice for calls
        address alice = address(0x1234);
        vm.deal(alice, 1 ether);
        // Alice calls lockInGuess for the first time
        bool success;
        vm.prank(alice);
        try c.lockInGuess{value: 1 ether}(keccak256("test")) {
            success = true;
        } catch {
            success = false;
        }
        // Reference contract: first call succeeds (success == true)
        // Buggy contract: first call reverts (success == false)
        // The difference is observable: the reference allows the call, the buggy does not
        // But actually the reference also requires msg.value == 1 ether, which we provide, so reference succeeds
        // The buggy version requires block != 0, and since it's the first call block=0, it reverts
        // Therefore reference: success = true, buggy: success = false
        // We assert that the call succeeded (which the reference does, but buggy does not)
        assertTrue(success);
    }
}

