        vm.deal(address(c), 1 ether);

        // Fund Alice with some ether
        address alice = address(0x1111);
        vm.deal(alice, 2 ether);

        // First call: lockInGuess should succeed in reference, but revert in buggy
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256("guess"));

        // Move to next block (so that second call is in a later block)
        vm.roll(block.number + 2);

        // Second call: in reference, it reverts because block != 0
        // In buggy, it succeeds because it requires block != 0 (which holds)
        vm.prank(alice);
        (bool ok, ) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", keccak256("guess2")));

        // Reference: second call reverts (ok == false)
        // Buggy: second call succeeds (ok == true)
        // We assert the reference behavior: should revert
        assertTrue(!ok, "Second lock-in should have reverted");
    }
}

