pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund accounts
        vm.deal(address(0x01), 2 ether);
        vm.deal(address(0x02), 2 ether);

        // Set up block for future blockhash
        vm.roll(10);

        // Actor 1: try lockInGuess with 1 ether on reference (should succeed)
        vm.prank(address(0x01));
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(10))));

        // Now try settle — should succeed on reference
        bool refSettleOk;
        vm.prank(address(0x01));
        try c.settle() {
            refSettleOk = true;
        } catch {
            refSettleOk = false;
        }

        // Actor 2: try lockInGuess with 1 ether on buggy (reverts, so no state change)
        vm.prank(address(0x02));
        (bool ok,) = address(c).call{value: 1 ether}(abi.encodeWithSignature("lockInGuess(bytes32)", keccak256(abi.encodePacked(blockhash(11)))));

        // Try settle for actor 2 — should revert because lockInGuess failed
        bool bugSettleOk;
        vm.prank(address(0x02));
        try c.settle() {
            bugSettleOk = true;
        } catch {
            bugSettleOk = false;
        }

        // Reference: settle succeeded (refSettleOk = true), bug: settle reverted (bugSettleOk = false)
        assertTrue(refSettleOk && !bugSettleOk);
    }
}

