contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, 2 ether);
        vm.deal(address(c), 1 ether); // fund the contract to cover initial deposit and potential transfers
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(block.number + 1))));
